insert into public.exercises ("id", "name", "primary_muscle_group", "secondary_muscle_groups", "equipment", "laterality", "rep_unit", "difficulty", "movement_pattern", "description", "why", "instructions", "setup", "execution", "breathing_cue", "form_cues", "common_mistakes", "progression_guidance", "regression_or_substitution", "recommended_rest_seconds", "is_custom", "owner_id", "created_at", "updated_at") values
  ('ex_barbell_squat', 'Barbell Squat', 'legs', ARRAY['glutes', 'core']::text[], 'barbell', 'bilateral', 'reps', 'advanced', 'squat', 'A compound lower-body lift that builds strength and size across the quads, glutes, and core.', 'The foundation of lower-body strength — it carries directly into everyday capability like stairs, floors, and getting back up off them.', ARRAY['Set the bar on your upper back and unrack it.', 'Squat to a comfortable depth, then drive through your feet to stand back up.']::text[], 'Set the bar on your upper back, unrack it, and set your feet roughly shoulder width apart.', 'Brace your core and squat down to a comfortable depth, then drive through your feet to stand back up.', 'Inhale and brace before you descend, exhale as you drive up.', ARRAY['Keep your chest up and core braced', 'Track your knees over your toes', 'Drive through your whole foot']::text[], ARRAY['Knees caving inward', 'Heels lifting off the floor', 'Rounding the lower back at the bottom']::text[], 'Add small plates once you can complete every set at the top of the rep range with 2-3 RIR.', 'A goblet squat or hack squat machine give you the same pattern with far less balance and lower-back demand — a smart swap if a barbell doesn''t suit your joints.', 180, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_bench_press', 'Bench Press', 'chest', ARRAY['shoulders', 'triceps']::text[], 'barbell', 'bilateral', 'reps', 'intermediate', 'horizontal_push', 'The classic horizontal press for building chest, shoulder, and triceps strength.', 'A cornerstone upper-body press — nothing builds raw pushing strength and chest muscle as efficiently.', ARRAY['Lie on the bench with your eyes under the bar.', 'Lower the bar to your mid-chest with control, then press back to lockout.']::text[], 'Lie back with your eyes under the bar, feet flat on the floor, and pull your shoulder blades together and down before you unrack it.', 'Lower the bar under control to your mid-chest, then press it back up to lockout without letting your hips leave the bench.', 'Breathe in on the way down, exhale as you drive the bar up.', ARRAY['Retract your shoulder blades before unracking', 'Keep a slight arch and your feet planted', 'Lower the bar under control to your chest']::text[], ARRAY['Bouncing the bar off the chest', 'Flaring the elbows out to 90 degrees', 'Lifting the hips off the bench']::text[], 'Once every set hits the top of the rep range with 2 RIR to spare, add 2.5-5 kg.', 'If your shoulders complain, swap in a machine chest press or dumbbell press — both let your arms move through a more natural path.', 150, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_incline_dumbbell_press', 'Incline Dumbbell Press', 'chest', ARRAY['shoulders', 'triceps']::text[], 'dumbbell', 'bilateral', 'reps', 'intermediate', 'horizontal_push', 'An incline press that shifts emphasis onto the upper chest.', 'Rounds out chest development through a press pattern that''s easier on the shoulders than a flat barbell press.', ARRAY['Set the bench to a 30-45 degree incline.', 'Press the dumbbells up until your arms are extended, then lower with control.']::text[], 'Set the bench to 30-45 degrees and bring the dumbbells to shoulder height, wrists stacked over elbows.', 'Press the dumbbells up and slightly together until your arms are extended, then lower with control back to chest level.', 'Inhale as the dumbbells lower, exhale as you press them up.', ARRAY['Set the bench between 30 and 45 degrees', 'Press the dumbbells up and slightly inward', 'Keep your wrists stacked over your elbows']::text[], ARRAY['Setting the incline too steep, shifting work to the shoulders', 'Letting the dumbbells drift too wide', 'Bouncing out of the bottom position']::text[], 'Move up to the next dumbbell increment once every set hits the top of the range with control.', 'A machine incline press removes the need to stabilise the dumbbells and is a fine substitute while you build shoulder comfort.', 120, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_lat_pulldown', 'Lat Pulldown', 'back', ARRAY['biceps']::text[], 'cable', 'bilateral', 'reps', 'beginner', 'vertical_pull', 'A vertical pulling movement that targets the lats through a controlled, supported range of motion.', 'Builds the back width and pulling strength of a pull-up while letting you dial in a weight you can control for clean reps.', ARRAY['Grip the bar wider than shoulder width.', 'Pull the bar down to your upper chest, then control it back up to a full stretch.']::text[], 'Sit tall, secure your knees under the pad, and grip the bar wider than shoulder width.', 'Pull the bar down to your upper chest, driving your elbows down and back, then control it back up to a full stretch.', 'Exhale as you pull down, inhale as you let the bar rise.', ARRAY['Lead with your elbows, not your hands', 'Pull the bar to your upper chest', 'Keep a slight backward lean, not a big swing']::text[], ARRAY['Pulling the bar behind the neck', 'Using body momentum to yank the weight down', 'Not controlling the weight back up']::text[], 'Add weight in small increments once you can complete every set with 2 good reps left in the tank.', 'As pulling strength builds, this is the natural stepping stone toward an assisted, then unassisted, pull-up.', 120, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_pull_up', 'Pull Up', 'back', ARRAY['biceps']::text[], 'bodyweight', 'bilateral', 'reps', 'advanced', 'vertical_pull', 'A bodyweight vertical pull that builds a strong back and grip.', 'The benchmark of relative pulling strength, and a great long-term goal once the lat pulldown feels easy.', ARRAY['Hang from the bar with an overhand grip.', 'Pull yourself up until your chin clears the bar, then lower back down under control.']::text[], 'Hang from the bar with an overhand grip, shoulders active rather than fully slack.', 'Pull yourself up until your chin clears the bar, then lower back down under control.', 'Exhale as you pull up, inhale as you lower.', ARRAY['Start from a full dead hang', 'Pull your chin over the bar, chest up', 'Lower back down under control']::text[], ARRAY['Kipping or swinging the legs for momentum', 'Only completing half the range of motion', 'Shrugging the shoulders up at the top']::text[], 'Build toward it with an assisted pull-up machine or resistance band, reducing assistance as you get stronger.', 'The lat pulldown is the direct substitute — same pattern, fully adjustable load.', 120, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_chest_supported_row', 'Chest-Supported Row', 'back', ARRAY['biceps', 'shoulders']::text[], 'dumbbell', 'bilateral', 'reps', 'beginner', 'horizontal_pull', 'A horizontal row performed chest-down on an incline bench, removing any need to stabilise the lower back.', 'Build upper-back strength and muscle while reducing the need to stabilise your torso.', ARRAY['Set the bench so your chest is supported and your feet are stable.', 'Drive your elbows back and pull toward your lower ribs, then lower under control.']::text[], 'Set the bench so your chest is supported and your feet are stable, and let the dumbbells hang straight down.', 'Drive your elbows back and pull toward your lower ribs. Pause briefly, then lower the weight under control.', 'Exhale as you row, inhale as you lower.', ARRAY['Think elbows, not hands', 'Pull to your lower ribs, not your chest', 'Squeeze your shoulder blades together at the top']::text[], ARRAY['Using momentum to swing the weight', 'Shrugging instead of pulling with the back', 'Cutting the range of motion short at the bottom']::text[], 'Add weight once you can complete every set through a full range with 2 RIR.', 'A chest-supported machine row is an equally good substitute if the incline-bench setup isn''t available.', 120, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_seated_cable_row', 'Seated Cable Row', 'back', ARRAY['biceps']::text[], 'cable', 'bilateral', 'reps', 'beginner', 'horizontal_pull', 'A horizontal pulling movement for back thickness.', 'Adds a second horizontal pulling angle so the mid-back gets trained from more than one direction each week.', ARRAY['Sit with knees slightly bent and grab the handle.', 'Pull the handle to your torso, then extend your arms back out with control.']::text[], 'Sit with knees slightly bent and grab the handle with your arms extended.', 'Pull the handle to your torso, squeezing your shoulder blades together, then extend your arms back out with control.', 'Exhale as you pull, inhale as you extend.', ARRAY['Sit tall with a slight forward hip hinge to start', 'Pull the handle to your torso, elbows close to the body', 'Squeeze your shoulder blades together at the finish']::text[], ARRAY['Rounding the lower back for extra range', 'Rocking the torso to build momentum', 'Shrugging instead of pulling with the back']::text[], 'Add weight once every set feels smooth and controlled at 2 RIR.', 'A machine row removes the seated-balance element entirely if lower-back comfort is a priority.', 90, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_shoulder_press', 'Shoulder Press', 'shoulders', ARRAY['triceps']::text[], 'dumbbell', 'bilateral', 'reps', 'intermediate', 'vertical_push', 'An overhead press that builds shoulder size and strength.', 'Direct overhead strength keeps everyday lifting — cupboards, luggage, grandkids — easy long after your 40s.', ARRAY['Press the dumbbells overhead until your arms are extended.', 'Lower back to shoulder height with control.']::text[], 'Sit or stand tall with the dumbbells at shoulder height, core braced.', 'Press the dumbbells overhead until your arms are extended, then lower back to shoulder height under control.', 'Exhale as you press up, inhale as you lower.', ARRAY['Brace your core to avoid arching your back', 'Press up and slightly together overhead', 'Lower with control to shoulder height']::text[], ARRAY['Excessive lower back arch', 'Flaring the elbows too far at the bottom', 'Not pressing to full lockout']::text[], 'Add reps first, then weight, once you can hit the top of the range for every set at 2 RIR.', 'A machine or seated shoulder press reduces the balance demand if standing overhead pressing bothers your lower back.', 120, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_lateral_raise', 'Lateral Raise', 'shoulders', '{}', 'dumbbell', 'bilateral', 'reps', 'beginner', 'isolation', 'An isolation move for the side deltoids that gives shoulders width without loading the joint heavily.', 'Builds the round, capped-shoulder look and shoulder-joint resilience with very little joint stress.', ARRAY['Raise the dumbbells out to the sides to shoulder height.', 'Lower with control.']::text[], 'Stand tall holding a light-to-moderate dumbbell in each hand at your sides.', 'Raise the dumbbells out to the sides to shoulder height, then lower with control.', 'Exhale as you raise, inhale as you lower.', ARRAY['Lead with your elbows, not your hands', 'Raise to about shoulder height', 'Keep a slight bend in the elbows throughout']::text[], ARRAY['Swinging the weights up with momentum', 'Shrugging the traps to lift higher', 'Raising above shoulder height']::text[], 'This is a rep-range exercise — chase smoother, more controlled reps before chasing heavier weight.', 'A cable lateral raise keeps tension on the shoulder throughout the movement and is gentler than a heavy dumbbell.', 60, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_bicep_curl', 'Bicep Curl', 'biceps', '{}', 'dumbbell', 'bilateral', 'reps', 'beginner', 'isolation', 'A classic isolation exercise for the biceps.', 'Finishes arm development and supports every pulling exercise in the programme.', ARRAY['Curl the dumbbells up towards your shoulders.', 'Lower back down with control.']::text[], 'Stand tall holding a dumbbell in each hand, arms extended, elbows pinned to your sides.', 'Curl the dumbbells up towards your shoulders, then lower back down with control.', 'Exhale as you curl up, inhale as you lower.', ARRAY['Keep your elbows pinned to your sides', 'Curl up while keeping your wrists straight', 'Lower fully under control']::text[], ARRAY['Swinging the torso for momentum', 'Letting the elbows drift forward', 'Not extending fully at the bottom']::text[], 'Add a small amount of weight once every set feels controlled with 1-2 RIR left.', 'A cable curl keeps tension constant throughout and is gentler on the wrists and elbows.', 60, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_tricep_pushdown', 'Tricep Pushdown', 'triceps', '{}', 'cable', 'bilateral', 'reps', 'beginner', 'isolation', 'An isolation move for the triceps using a cable stack.', 'Finishes off arm development and reinforces lockout strength for every pressing movement.', ARRAY['Push the bar down until your arms are fully extended.', 'Control the weight back up.']::text[], 'Stand tall at the cable stack, grip the bar, and pin your elbows to your sides.', 'Push the bar down until your arms are fully extended, then control the weight back up to 90 degrees.', 'Exhale as you push down, inhale as you return.', ARRAY['Keep your elbows pinned to your sides', 'Extend fully without slamming the lockout', 'Control the weight back up to 90 degrees']::text[], ARRAY['Letting the elbows flare out or drift forward', 'Leaning on the body for momentum', 'Only using a partial range of motion']::text[], 'Add a small amount of weight once every set feels controlled at 1-2 RIR.', 'A resistance-band pushdown or dumbbell overhead extension both work well if the cable stack is busy.', 60, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_face_pull', 'Face Pull', 'shoulders', ARRAY['back']::text[], 'cable', 'bilateral', 'reps', 'beginner', 'horizontal_pull', 'A rear-delt and upper-back pull that also works the rotator cuff — good for shoulder health as much as size.', 'Balances out all the pressing in the programme and keeps the shoulders healthy for the long run.', ARRAY['Set a cable or band at roughly face height.', 'Pull towards your face, splitting your hands apart as they arrive.', 'Finish with your hands beside your ears, elbows high.', 'Return with control.']::text[], 'Set a cable or band at roughly face height and take an overhand or rope grip.', 'Pull towards your face, splitting your hands apart as they arrive, finishing with your hands beside your ears and elbows high.', 'Exhale as you pull, inhale as you return.', ARRAY['Lead with your elbows, pulling high and wide', 'Finish with your hands level with your ears', 'Keep the movement slow and controlled, not yanked']::text[], ARRAY['Pulling low, towards the chest instead of the face', 'Using too much weight and turning it into a row', 'Rushing the return instead of controlling it']::text[], 'This is a technique-first exercise — add weight only once your form stays clean for every rep.', 'A band face pull works just as well and is easy to do almost anywhere.', 60, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_romanian_deadlift', 'Romanian Deadlift', 'legs', ARRAY['glutes']::text[], 'barbell', 'bilateral', 'reps', 'intermediate', 'hinge', 'A hip-hinge movement that targets the hamstrings and glutes.', 'Trains the hip hinge — the pattern behind picking things up safely — while building the entire back of the legs.', ARRAY['Hold the bar with a shoulder-width grip.', 'Hinge at the hips, lowering the bar along your legs.', 'Drive your hips forward to return to standing.']::text[], 'Hold the bar with a shoulder-width grip and a soft bend in your knees.', 'Hinge at the hips, lowering the bar along your legs until you feel a stretch in your hamstrings, then drive your hips forward to return to standing.', 'Inhale as you hinge down, exhale as you stand up.', ARRAY['Hinge at the hips with a soft knee bend', 'Keep the bar close to your legs throughout', 'Feel the stretch in your hamstrings, not your lower back']::text[], ARRAY['Rounding the lower back', 'Bending the knees too much, turning it into a squat', 'Letting the bar drift away from the legs']::text[], 'Add weight once you can hinge through a full, comfortable range for every set at 2 RIR.', 'A dumbbell RDL is easier to control and a good starting point before moving to a barbell.', 120, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_leg_curl', 'Leg Curl', 'legs', '{}', 'machine', 'bilateral', 'reps', 'beginner', 'isolation', 'An isolation exercise for the hamstrings.', 'Balances out all the quad and hip-hinge work with direct hamstring strength — good insurance for knee health.', ARRAY['Curl the pad towards your glutes.', 'Lower back down with control.']::text[], 'Lie face down, or sit on a seated machine, and hook your heels under the pad.', 'Curl the pad towards your glutes through a full range, then lower back down with control.', 'Exhale as you curl, inhale as you lower.', ARRAY['Keep your hips pressed into the pad', 'Curl through a full range of motion', 'Lower back down under control']::text[], ARRAY['Lifting the hips off the pad', 'Using a fast, jerky range of motion', 'Only completing a partial curl']::text[], 'Add weight once every set feels controlled with 1-2 RIR left in reserve.', 'A stability-ball hamstring curl is a solid substitute if a leg curl machine isn''t available.', 60, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_leg_extension', 'Leg Extension', 'legs', '{}', 'machine', 'bilateral', 'reps', 'beginner', 'isolation', 'An isolation exercise for the quads.', 'Direct quad work that''s easy on the lower back and a useful gauge of knee-friendly strength progress.', ARRAY['Extend your legs until straight.', 'Lower back down with control.']::text[], 'Sit with your back flat against the pad and your shins behind the lower pad.', 'Extend your legs until straight, then lower back down with control.', 'Exhale as you extend, inhale as you lower.', ARRAY['Keep your back flat against the pad', 'Extend to full knee lockout without straining', 'Lower under control rather than dropping the weight']::text[], ARRAY['Swinging the weight up with momentum', 'Not controlling the descent', 'Positioning the pad too high or low on the shin']::text[], 'Add weight once every set feels smooth and controlled at 1-2 RIR.', 'Reduce the range of motion slightly at the top if you feel any pinching at full lockout.', 60, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_calf_raise', 'Calf Raise', 'legs', '{}', 'machine', 'bilateral', 'reps', 'beginner', 'isolation', 'An isolation exercise for the calves.', 'Strong calves support the ankle for walking, running, and every lower-body lift in the programme.', ARRAY['Rise up onto your toes as high as possible.', 'Lower back down under control.']::text[], 'Stand on the platform with the balls of your feet supported and your heels free to drop.', 'Rise up onto your toes as high as possible, pause briefly, then lower back down under control until you feel a stretch.', 'Exhale as you rise, inhale as you lower.', ARRAY['Rise onto your toes through the full range', 'Pause briefly at the top', 'Lower until you feel a stretch in the calf']::text[], ARRAY['Bouncing at the bottom instead of pausing', 'Using a partial range of motion', 'Rushing through reps without control']::text[], 'Calves respond well to higher reps — add weight once 15 reps feels controlled and comfortable.', 'A seated calf raise machine shifts emphasis onto the soleus and is easier on the knees if standing bothers you.', 45, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_plank', 'Plank', 'core', '{}', 'bodyweight', 'bilateral', 'seconds', 'beginner', 'other', 'A static core-stability hold that trains the abs, obliques, and lower back to resist movement.', 'Builds the trunk stability that underpins every lift in this programme, and doubles as a low-impact finisher.', ARRAY['Support yourself on your forearms and toes in a straight line.', 'Hold the position, keeping your hips level and core braced.']::text[], 'Support yourself on your forearms and toes, elbows under your shoulders, body in a straight line from head to heels.', 'Hold the position, keeping your hips level and your core braced, for the target time.', 'Breathe steadily throughout — don''t hold your breath.', ARRAY['Keep a straight line from head to heels', 'Squeeze your glutes and brace your core', 'Keep your hips level, not sagging or piked']::text[], ARRAY['Letting the hips sag toward the floor', 'Piking the hips up to make it easier', 'Holding your breath']::text[], 'Add 10-15 seconds once the current hold feels comfortably controlled for the full time.', 'Drop to your knees to shorten the lever if a full plank is too demanding to hold with good form.', 45, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_goblet_squat', 'Goblet Squat', 'legs', ARRAY['glutes', 'core']::text[], 'dumbbell', 'bilateral', 'reps', 'beginner', 'squat', 'A front-loaded squat holding a single dumbbell at the chest.', 'The most approachable way to learn the squat pattern — the front load naturally keeps your torso upright.', ARRAY['Hold a dumbbell vertically against your chest.', 'Squat down between your knees, then drive back up.']::text[], 'Hold a dumbbell by one end vertically against your chest, elbows pointing down.', 'Squat down, letting your elbows track between your knees, until your thighs are at least parallel, then drive back up.', 'Inhale and brace before you descend, exhale as you stand.', ARRAY['Keep the dumbbell close to your chest', 'Sit down between your knees, not back', 'Drive through your whole foot']::text[], ARRAY['Letting the dumbbell drift away from the chest', 'Rounding the upper back', 'Rising onto the toes']::text[], 'Move to a heavier dumbbell once you can complete every set with 2-3 RIR and full depth.', 'A bodyweight squat to a box removes the load entirely while you build the pattern.', 90, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_leg_press', 'Leg Press', 'legs', ARRAY['glutes']::text[], 'machine', 'bilateral', 'reps', 'beginner', 'squat', 'A machine squat pattern that removes the balance and spinal-loading demands of a barbell squat.', 'Lets you load the legs hard with very little lower-back or balance demand — a favourite for training around joint niggles.', ARRAY['Set your feet shoulder-width on the platform.', 'Lower under control, then press back to just short of lockout.']::text[], 'Sit back in the machine and place your feet shoulder-width apart on the platform.', 'Lower the platform under control until your knees reach about 90 degrees, then press back up without locking the knees out hard.', 'Inhale as the platform lowers, exhale as you press.', ARRAY['Keep your whole foot flat on the platform', 'Lower until your knees reach about 90 degrees', 'Stop just short of locking the knees']::text[], ARRAY['Letting the knees cave inward', 'Lowering so far the lower back rounds off the seat', 'Slamming the weight at lockout']::text[], 'Add weight once every set reaches the top of the rep range with 2 RIR.', 'A goblet squat is the natural substitute if a leg press machine isn''t available.', 120, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_walking_lunge', 'Walking Lunge', 'legs', ARRAY['glutes', 'core']::text[], 'dumbbell', 'unilateral', 'reps', 'intermediate', 'lunge', 'A forward-stepping lunge, loaded with dumbbells, trained one leg at a time.', 'Builds single-leg strength and balance — the kind of capability that keeps stairs and uneven ground easy.', ARRAY['Step forward into a lunge, lowering the back knee toward the floor.', 'Drive through the front foot to step into the next lunge.']::text[], 'Stand tall holding a dumbbell in each hand at your sides.', 'Step forward, lowering your back knee toward the floor with control, then drive through your front foot to stand and step into the next lunge.', 'Inhale as you step and lower, exhale as you drive up.', ARRAY['Keep your torso upright', 'Lower the back knee toward the floor, not the ground', 'Drive through the front heel']::text[], ARRAY['Letting the front knee drift past the toes aggressively', 'Taking too short a step', 'Leaning far forward']::text[], 'Add weight once every set feels stable and controlled through the full walk.', 'A stationary split squat removes the balance challenge of stepping while training the same pattern.', 90, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_hip_thrust', 'Hip Thrust', 'glutes', ARRAY['legs']::text[], 'barbell', 'bilateral', 'reps', 'intermediate', 'hinge', 'A hip-extension movement performed with the upper back supported on a bench.', 'The most direct way to build glute strength, which underpins hip stability and a lot of everyday power.', ARRAY['Rest your upper back on a bench with the bar over your hips.', 'Drive your hips up until your body is in a straight line, then lower with control.']::text[], 'Rest your upper back on a bench, feet flat on the floor, and roll the bar over your hips.', 'Drive your hips up until your body forms a straight line from shoulders to knees, squeeze at the top, then lower with control.', 'Inhale at the bottom, exhale as you drive up.', ARRAY['Drive through your heels', 'Squeeze your glutes hard at the top', 'Keep your chin tucked, not looking up']::text[], ARRAY['Overextending the lower back at the top', 'Pushing through the toes instead of the heels', 'Using a small, partial range of motion']::text[], 'Add weight once every set locks out fully with 2 RIR.', 'A single-leg glute bridge on the floor is a good bodyweight starting point.', 90, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_dumbbell_rdl', 'Dumbbell Romanian Deadlift', 'legs', ARRAY['glutes']::text[], 'dumbbell', 'bilateral', 'reps', 'beginner', 'hinge', 'The Romanian deadlift hip hinge, loaded with dumbbells instead of a barbell.', 'Easier to control and feel than a barbell RDL — a good place to learn the hip hinge properly.', ARRAY['Hold a dumbbell in each hand in front of your thighs.', 'Hinge at the hips, lowering the dumbbells along your legs, then stand back up.']::text[], 'Hold a dumbbell in each hand in front of your thighs, knees softly bent.', 'Hinge at the hips, lowering the dumbbells along your legs until you feel a stretch in your hamstrings, then drive your hips forward to stand.', 'Inhale as you hinge down, exhale as you stand.', ARRAY['Keep the dumbbells close to your legs', 'Push your hips back, not down', 'Stop once you feel the hamstring stretch']::text[], ARRAY['Rounding the lower back', 'Squatting the movement instead of hinging', 'Letting the dumbbells drift forward']::text[], 'Move up to the next dumbbell increment once the hinge feels fully controlled at the top of the rep range.', 'A barbell Romanian deadlift is the natural progression once the pattern feels solid.', 90, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_machine_chest_press', 'Machine Chest Press', 'chest', ARRAY['shoulders', 'triceps']::text[], 'machine', 'bilateral', 'reps', 'beginner', 'horizontal_push', 'A guided horizontal press that trains the chest without the stabilisation demands of a free-weight press.', 'Lets you push the chest hard with a fixed, joint-friendly path — a reliable staple for pressing volume.', ARRAY['Sit with the handles at chest height.', 'Press forward to extension, then return under control.']::text[], 'Sit tall with the handles at chest height and your back flat against the pad.', 'Press the handles forward until your arms are extended without locking out hard, then return under control to the start.', 'Exhale as you press, inhale as you return.', ARRAY['Keep your shoulder blades pinned to the pad', 'Press forward, not up', 'Control the return rather than letting it snap back']::text[], ARRAY['Flaring the elbows to 90 degrees', 'Lifting the shoulders off the pad', 'Using a partial range of motion']::text[], 'Add weight once every set reaches the top of the rep range at 2 RIR.', 'A dumbbell bench press is the free-weight equivalent once you want more range and stabiliser work.', 120, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_dumbbell_bench_press', 'Dumbbell Bench Press', 'chest', ARRAY['shoulders', 'triceps']::text[], 'dumbbell', 'bilateral', 'reps', 'intermediate', 'horizontal_push', 'A flat press performed with dumbbells, allowing a more natural bar path and greater range of motion.', 'Trains each side independently, evening out any strength imbalance a barbell can hide.', ARRAY['Press the dumbbells up from chest height.', 'Lower with control back to chest level.']::text[], 'Lie on the bench with a dumbbell in each hand at chest height, elbows under your wrists.', 'Press the dumbbells up until your arms are extended, then lower with control back to chest level.', 'Inhale as the dumbbells lower, exhale as you press.', ARRAY['Keep your feet planted and a slight arch', 'Press the dumbbells up and slightly together', 'Lower until you feel a stretch across the chest']::text[], ARRAY['Letting the dumbbells drift wide at the bottom', 'Bouncing out of the bottom position', 'Flaring the elbows to 90 degrees']::text[], 'Move to the next dumbbell increment once every set hits the top of the range with 2 RIR.', 'A machine chest press removes the need to stabilise the dumbbells independently.', 120, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_cable_fly', 'Cable Fly', 'chest', ARRAY['shoulders']::text[], 'cable', 'bilateral', 'reps', 'beginner', 'isolation', 'An isolation move that stretches and squeezes the chest through a wide arc.', 'Adds chest volume without taxing the shoulders and triceps the way another pressing exercise would.', ARRAY['Bring the handles together in front of your chest.', 'Return with control to a comfortable stretch.']::text[], 'Stand centred between two cable stacks set roughly at chest height, a handle in each hand.', 'Bring the handles together in front of your chest in a hugging arc, squeeze, then return with control to a comfortable stretch.', 'Exhale as you bring the handles together, inhale as you return.', ARRAY['Keep a slight, fixed bend in the elbows', 'Lead with your hands, not your shoulders', 'Squeeze at the centre, don''t just let the handles clang']::text[], ARRAY['Turning it into a press by bending the elbows more', 'Using so much weight the shoulders round forward', 'Stopping short of a real stretch at the back']::text[], 'This is a feel-focused isolation move — add weight only once the squeeze and stretch both stay clean.', 'A dumbbell fly on a flat bench is a good substitute without a cable station.', 60, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_machine_row', 'Machine Row', 'back', ARRAY['biceps']::text[], 'machine', 'bilateral', 'reps', 'beginner', 'horizontal_pull', 'A chest-supported, guided rowing movement for back thickness.', 'Gives a second horizontal pulling angle with zero lower-back involvement — an easy, repeatable back builder.', ARRAY['Sit with your chest against the pad.', 'Pull the handles to your torso, then extend back out under control.']::text[], 'Sit with your chest against the pad and grip the handles with your arms extended.', 'Pull the handles to your torso, driving your elbows back, then extend back out under control.', 'Exhale as you pull, inhale as you extend.', ARRAY['Keep your chest pinned to the pad', 'Drive your elbows back, not out', 'Squeeze your shoulder blades together at the finish']::text[], ARRAY['Lifting the chest off the pad to cheat more weight', 'Shrugging instead of pulling with the back', 'Using a fast, bouncing tempo']::text[], 'Add weight once every set feels smooth and controlled through the full range.', 'A seated cable row is the equivalent without a dedicated row machine.', 90, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_dumbbell_shoulder_press', 'Dumbbell Shoulder Press', 'shoulders', ARRAY['triceps']::text[], 'dumbbell', 'bilateral', 'reps', 'intermediate', 'vertical_push', 'An overhead press performed with dumbbells for independent, natural-path shoulder work.', 'Lets each shoulder find its own natural pressing groove, which barbell pressing can sometimes force out of.', ARRAY['Press the dumbbells overhead from shoulder height.', 'Lower back to shoulder height with control.']::text[], 'Sit or stand tall with a dumbbell at each shoulder, palms facing forward.', 'Press the dumbbells overhead until your arms are extended, then lower back to shoulder height under control.', 'Exhale as you press up, inhale as you lower.', ARRAY['Brace your core rather than arching your back', 'Press up and slightly inward', 'Lower all the way back to shoulder height']::text[], ARRAY['Arching the lower back to press more weight', 'Only pressing through a partial range', 'Flaring the elbows too wide at the bottom']::text[], 'Move to the next dumbbell increment once every set reaches the top of the range at target RIR.', 'A machine shoulder press removes the stabilisation demand if that''s the limiting factor.', 90, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_hammer_curl', 'Hammer Curl', 'biceps', '{}', 'dumbbell', 'bilateral', 'reps', 'beginner', 'isolation', 'A neutral-grip curl that shares the load between the biceps and forearm.', 'Builds grip and forearm strength alongside the biceps — useful carryover for rows and pulls.', ARRAY['Curl the dumbbells up with palms facing each other.', 'Lower back down with control.']::text[], 'Stand tall holding a dumbbell in each hand, palms facing your body.', 'Curl the dumbbells up while keeping your palms facing each other, then lower back down with control.', 'Exhale as you curl up, inhale as you lower.', ARRAY['Keep your elbows pinned to your sides', 'Keep your wrists neutral throughout', 'Lower fully under control']::text[], ARRAY['Swinging the torso for momentum', 'Letting the elbows drift forward', 'Rushing the lowering phase']::text[], 'Add a small amount of weight once every set feels controlled with 1-2 RIR left.', 'A standard dumbbell curl trains the same muscles with a supinated grip.', 60, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_overhead_tricep_extension', 'Overhead Tricep Extension', 'triceps', '{}', 'dumbbell', 'bilateral', 'reps', 'beginner', 'isolation', 'An overhead isolation move that stretches and works the long head of the triceps.', 'Trains the triceps through a deeper stretch than a pushdown, rounding out arm development.', ARRAY['Lower the dumbbell behind your head with control.', 'Extend back up to full elbow lockout.']::text[], 'Hold a single dumbbell overhead with both hands, arms extended.', 'Lower the dumbbell behind your head by bending at the elbows, then extend back up to full lockout.', 'Inhale as you lower, exhale as you extend.', ARRAY['Keep your elbows pointing forward, not flared', 'Lower until you feel a full stretch', 'Extend fully without arching the back']::text[], ARRAY['Letting the elbows flare out wide', 'Using momentum from the shoulders', 'Arching the lower back to move more weight']::text[], 'Add a small amount of weight once every set feels controlled with 1-2 RIR left.', 'A cable tricep pushdown is a good substitute if overhead positions bother your shoulders.', 60, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_farmers_carry', 'Farmer''s Carry', 'full_body', ARRAY['core']::text[], 'dumbbell', 'bilateral', 'seconds', 'beginner', 'carry', 'Walking for distance or time while holding a heavy dumbbell in each hand.', 'Builds grip, trunk stability and total-body durability — as functional as strength training gets.', ARRAY['Pick up a heavy dumbbell in each hand.', 'Walk tall for the target distance or time.']::text[], 'Stand tall between two heavy dumbbells, hinge down, and pick them up with a flat back.', 'Walk tall for the target distance or time, keeping your shoulders back and core braced throughout.', 'Breathe steadily throughout — don''t hold your breath.', ARRAY['Stand as tall as possible', 'Keep your shoulders back, not shrugged', 'Take controlled, even steps']::text[], ARRAY['Leaning to one side', 'Shrugging the shoulders up toward the ears', 'Rushing the steps and losing control']::text[], 'Add weight once the current load feels fully controlled for the whole distance or time.', 'Carrying a single dumbbell on one side (a suitcase carry) is an easier entry point.', 90, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_pallof_press', 'Pallof Press', 'core', '{}', 'cable', 'bilateral', 'reps', 'beginner', 'anti_rotation', 'An anti-rotation core exercise performed by pressing a cable straight out from the chest.', 'Trains the core to resist rotation rather than just flex — a more functional core stimulus than a crunch.', ARRAY['Press the handle straight out from your chest.', 'Resist rotation, then return under control.']::text[], 'Stand side-on to the cable stack, handle held at your chest with both hands.', 'Press the handle straight out from your chest, resisting the pull to rotate toward the machine, then return under control.', 'Exhale as you press out, inhale as you return.', ARRAY['Keep your hips and shoulders square', 'Press straight out, not across your body', 'Resist the pull rather than fighting it with your arms alone']::text[], ARRAY['Letting the hips rotate toward the machine', 'Pressing too fast to feel the resistance', 'Standing too close, reducing the cable angle']::text[], 'Add weight once you can hold a square, controlled position for every rep.', 'A resistance band anti-rotation press works the same pattern without a cable station.', 60, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_cable_crunch', 'Cable Crunch', 'core', '{}', 'cable', 'bilateral', 'reps', 'beginner', 'isolation', 'A kneeling ab isolation move using a cable for resistance through a full crunching range.', 'Lets you add real resistance to ab training once bodyweight holds like a plank stop being challenging.', ARRAY['Curl your torso down toward your knees.', 'Return with control to the starting position.']::text[], 'Kneel below the cable stack, holding the rope at your forehead with elbows in.', 'Curl your torso down toward your knees, leading with your ribs, then return with control.', 'Exhale as you curl down, inhale as you return.', ARRAY['Curl from the ribs, not the hips', 'Keep the hips relatively still', 'Control the return rather than letting it snap back']::text[], ARRAY['Pulling with the arms instead of curling the torso', 'Using the hips to yank the weight down', 'Choosing a weight so heavy the range shortens']::text[], 'Add weight once every rep still curls through a full, controlled range.', 'A bodyweight crunch or plank works the same muscles without a cable station.', 60, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_push_up', 'Push-Up', 'chest', ARRAY['shoulders', 'triceps']::text[], 'bodyweight', 'bilateral', 'reps', 'beginner', 'horizontal_push', 'A horizontal press performed against the floor, using bodyweight instead of a bar or dumbbells.', 'The most equipment-free way to train the same pressing pattern as a bench press — useful anywhere, anytime.', ARRAY['Set your hands slightly wider than shoulder width.', 'Lower your chest to the floor, then press back up.']::text[], 'Start in a plank with hands slightly wider than shoulder width.', 'Lower your chest toward the floor under control, then press back up to a straight-arm plank.', 'Inhale as you lower, exhale as you press up.', ARRAY['Keep your body in a straight line', 'Keep your elbows at roughly 45 degrees, not flared out']::text[], ARRAY['Hips sagging toward the floor', 'Flaring the elbows straight out to the sides']::text[], 'Once bodyweight feels easy for every rep, elevate your feet or add a weighted vest.', 'A knee push-up or an incline push-up (hands on a bench) reduce the load if a full push-up is too much.', 90, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_hack_squat', 'Hack Squat', 'legs', ARRAY['glutes']::text[], 'machine', 'bilateral', 'reps', 'intermediate', 'squat', 'A machine squat performed on a fixed, angled sled, taking balance demands out of the movement.', 'Trains the same knee-dominant pattern as a barbell squat with the bar''s balance demand removed by the machine.', ARRAY['Set your feet shoulder width apart on the platform.', 'Lower under control, then drive back up.']::text[], 'Set your shoulders under the pads and your feet shoulder width apart on the platform.', 'Lower under control to a comfortable depth, then drive through your feet to extend back up.', 'Inhale before descending, exhale as you drive up.', ARRAY['Keep your whole foot in contact with the platform', 'Control the descent rather than dropping into it']::text[], ARRAY['Letting the knees cave inward', 'Only lowering a few inches']::text[], 'Add small increments once every set reaches the top of the rep range comfortably.', 'A goblet squat trains the same pattern with far less external load if the machine is unavailable.', 150, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_bulgarian_split_squat', 'Bulgarian Split Squat', 'legs', ARRAY['glutes']::text[], 'dumbbell', 'unilateral', 'reps', 'advanced', 'squat', 'A single-leg squat with the rear foot elevated behind you, trained one leg at a time.', 'Builds single-leg strength and balance that a two-footed squat can''t reach on its own.', ARRAY['Rest your rear foot on a bench behind you.', 'Lower your back knee toward the floor, then drive back up.']::text[], 'Stand a couple of feet in front of a bench, resting the top of your rear foot on it.', 'Lower your back knee toward the floor under control, then drive through your front foot to stand.', 'Inhale as you lower, exhale as you drive up.', ARRAY['Keep most of your weight through the front foot', 'Keep your torso upright']::text[], ARRAY['Letting the front knee drift far past the toes', 'Pushing off the back foot instead of the front']::text[], 'Add dumbbell weight once every set on both legs feels stable and controlled.', 'A goblet squat removes the single-leg balance demand while training a related pattern.', 120, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_barbell_row', 'Barbell Row', 'back', ARRAY['biceps', 'shoulders']::text[], 'barbell', 'bilateral', 'reps', 'intermediate', 'horizontal_pull', 'A bent-over horizontal pull performed with a barbell, building back thickness and pulling strength.', 'One of the most direct ways to build back strength and thickness through a horizontal pulling pattern.', ARRAY['Hinge at the hips holding the bar in front of your thighs.', 'Pull the bar to your lower ribs, then lower with control.']::text[], 'Hinge forward from the hips until your torso is roughly 45 degrees, holding the bar with an overhand grip.', 'Pull the bar toward your lower ribs, squeezing your shoulder blades together, then lower with control.', 'Inhale at the bottom, exhale as you pull.', ARRAY['Keep your back flat, not rounded', 'Pull with your elbows, not your hands']::text[], ARRAY['Rounding the lower back', 'Using momentum to heave the weight up']::text[], 'Add small plates once every set is completed with a flat back and full control.', 'A chest-supported row removes the lower-back demand of holding the hinge position.', 150, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('ex_one_arm_dumbbell_row', 'One-Arm Dumbbell Row', 'back', ARRAY['biceps']::text[], 'dumbbell', 'unilateral', 'reps', 'beginner', 'horizontal_pull', 'A horizontal pull performed one arm at a time, with the opposite hand and knee braced on a bench.', 'Trains the same pulling pattern as a barbell row with a supported torso, removing the lower-back demand entirely.', ARRAY['Brace one hand and knee on a bench, dumbbell in the other hand.', 'Pull the dumbbell to your hip, then lower with control.']::text[], 'Brace one knee and hand on a bench with your back flat, holding a dumbbell in the free hand.', 'Pull the dumbbell up toward your hip, leading with your elbow, then lower with control.', 'Inhale at the bottom, exhale as you pull.', ARRAY['Keep your back flat throughout', 'Avoid twisting your torso as you pull']::text[], ARRAY['Twisting the torso to help lift the weight', 'Using a short, incomplete range of motion']::text[], 'Add weight once every set on both sides feels controlled through a full range.', 'A chest-supported row trains both sides together if single-arm balance is a limiting factor.', 90, false, NULL, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
insert into public.exercise_substitutions ("exercise_id", "substitute_exercise_id") values
  ('ex_barbell_squat', 'ex_leg_press'),
