insert into public.programs ("id", "owner_id", "name", "description", "category", "target_audience", "difficulty", "days_per_week", "estimated_session_minutes_low", "estimated_session_minutes_high", "primary_goal", "secondary_goals", "philosophy", "progression_method", "deload_strategy", "is_custom", "created_at", "updated_at") values
  ('program_ppl', NULL, 'Foundation 40+', 'Build strength. Keep muscle. Move well. Stay capable.', 'push_pull_legs', 'Adults 40+ who want one dependable, sustainable strength and physique split.', 'intermediate', 3, 45, 55, 'strength_and_muscle', ARRAY['longevity']::text[], 'A balanced push/pull/legs split run at 1-3 RIR — enough effort to drive progress, never so much that recovery suffers.', 'When every set of an exercise reaches the top of its rep range at the target RIR, add a small amount of weight next session.', 'Every 6-8 weeks, or any week that feels unusually heavy, cut sets by roughly a third and stay at the same weight.', false, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('program_ppl_hypertrophy_4', NULL, 'PPL Hypertrophy 4', 'A four-day rotation through push, pull and legs for more total muscle-building volume.', 'push_pull_legs', 'Lifters who can commit to four sessions a week and want more size, not just strength.', 'intermediate', 4, 50, 60, 'build_muscle', NULL, 'The three days rotate continuously (Push, Pull, Legs, Push, then Pull, Legs, Push... ) rather than resetting each week, so frequency stays high without a punishing 6-day schedule.', 'Per exercise: once every set reaches the top of the rep range at target RIR, add weight next time that exercise comes up.', 'Every 5-6 weeks, take a lighter week at roughly 60% of normal sets before resuming.', false, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('program_ppl_lower_fatigue_3', NULL, 'Lower-Fatigue PPL 3', 'The same push/pull/legs shape with meaningfully less systemic fatigue — fewer heavy leg sets and no spinal-loading hinge.', 'push_pull_legs', 'Anyone who likes PPL''s structure but finds three heavy leg days a week too draining to sustain.', 'beginner', 3, 40, 50, 'longevity', ARRAY['general_fitness']::text[], 'Genuinely reduced fatigue, not just a renamed programme: the leg day drops the barbell squat and Romanian deadlift entirely in favour of machine work at a higher RIR, and every day runs one fewer exercise.', 'Add weight once every set hits the top of the rep range at target RIR — the same rule as Foundation 40+, applied more conservatively.', 'Deloads are rarely needed here given the lower baseline fatigue; take one if progress stalls for 2+ weeks in a row.', false, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('program_ppl_strength_hypertrophy_3', NULL, 'Strength + Hypertrophy PPL 3', 'Each day opens with a low-rep strength set on the main lift, then finishes with hypertrophy-range accessory work.', 'push_pull_legs', 'Experienced lifters who want a strength top set without giving up hypertrophy volume.', 'advanced', 3, 55, 65, 'strength_and_muscle', NULL, 'Mixed rep ranges within a session — a heavier, lower-rep main lift for strength, then higher-rep accessories for muscle — rather than one rep range for the whole day.', 'The main lift progresses on load once it hits the top of its range at 2 RIR; accessories progress on reps first, then load.', 'Every 6 weeks, drop the main lift''s top set and run accessories only at reduced volume for one week.', false, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('program_full_body_foundation_3', NULL, 'Foundation Full Body 3', 'A classic three-day full-body split — each session trains every major movement pattern once.', 'full_body', 'Anyone who wants maximum results from exactly three weekly sessions.', 'beginner', 3, 45, 55, 'strength_and_muscle', NULL, 'Training every muscle group three times a week on a modest per-session volume beats hammering it once with a huge one.', 'Per exercise: once every set reaches the top of the rep range at target RIR, add weight next time it appears.', 'Every 6-8 weeks, cut sets by about a third for one week at the same weights.', false, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('program_full_body_hypertrophy_3', NULL, 'Full Body Hypertrophy 3', 'The full-body pattern with higher rep ranges and extra isolation work for more total muscle stimulus.', 'full_body', 'Lifters chasing size who still only have three days a week to train.', 'intermediate', 3, 50, 60, 'build_muscle', NULL, 'Slightly higher volume per session than Foundation Full Body, with an isolation exercise added to each pattern.', 'Add weight per exercise once every set reaches the top of the range at target RIR; isolation work can chase reps for longer before adding load.', 'Every 5-6 weeks, run one week at roughly 60% of normal sets.', false, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('program_full_body_minimalist_3', NULL, 'Full Body Minimalist 3', 'The shortest, simplest way to touch every muscle group three times a week — four exercises a session, no filler.', 'full_body', 'Busy professionals who need real results from roughly 30 minutes, three times a week.', 'beginner', 3, 30, 35, 'busy_professional', ARRAY['general_fitness']::text[], 'Four compound movements per session, no accessories — if a set doesn''t earn its place, it isn''t in this programme.', 'Add weight once every set of an exercise reaches the top of the rep range at target RIR.', 'The volume here is already low; if progress stalls for 2+ weeks, take a week at the same weight for fewer sets rather than deloading load.', false, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('program_full_body_over40_3', NULL, 'Full Body Over-40 3', 'A joint-friendly full-body split: slower eccentrics, machine-first exercise selection, and more reps in reserve.', 'full_body', 'Adults 40+ prioritising recovery and joint health without giving up meaningful strength work.', 'beginner', 3, 45, 55, 'longevity', ARRAY['general_fitness']::text[], 'Every choice here is deliberate: machine and dumbbell variations instead of maximal barbell lifts, a slower 4-1-1-0 tempo throughout, 2-3 RIR on everything, and no exercise pushed toward failure.', 'Add weight only once every set reaches the top of the range while the tempo and RIR both stay on target — reps and control come first.', 'Every 4th week, reduce every exercise by one set regardless of how training has felt — a built-in, not reactive, deload.', false, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('program_full_body_rotating_4', NULL, 'Full Body 4 (Rotating)', 'Two full-body sessions, alternating A/B/A/B, for four sessions a week without repeating a day back-to-back.', 'full_body', 'Lifters who want full-body frequency with more weekly volume than three days allows.', 'intermediate', 4, 45, 55, 'strength_and_muscle', NULL, 'Only two templates, rotating continuously — every muscle group is trained twice a week without needing a rigid calendar schedule.', 'Add weight per exercise once every set reaches the top of the range at target RIR.', 'Every 6 weeks, run one week at roughly two-thirds of normal sets.', false, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('program_upper_lower_strength_4', NULL, 'Upper/Lower Strength 4', 'Two upper and two lower sessions a week, built around lower-rep, higher-effort main lifts.', 'upper_lower', 'Intermediate-to-advanced lifters chasing strength who can train four days a week.', 'advanced', 4, 50, 60, 'get_stronger', ARRAY['build_muscle']::text[], 'Each muscle group is trained twice a week at a lower rep range (5-8) so more total weight can be handled without excessive fatigue.', 'Add weight once every set of the main lift reaches the top of the range at 2 RIR.', 'Every 4-5 weeks, take a lighter week at the same weights for roughly two-thirds of normal sets.', false, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('program_upper_lower_hypertrophy_4', NULL, 'Upper/Lower Hypertrophy 4', 'The same four-day upper/lower shape, tuned for muscle: higher reps, more isolation, more total sets.', 'upper_lower', 'Lifters who want the classic 10-20 weekly sets per muscle group without training more than four days.', 'intermediate', 4, 55, 65, 'build_muscle', NULL, 'Twice-weekly frequency per muscle group at 8-15 reps sits in the sweet spot the hypertrophy literature keeps landing on.', 'Add weight per exercise once every set reaches the top of the range at target RIR; isolation work can chase reps before adding load.', 'Every 5-6 weeks, run one week at roughly 60% of normal sets.', false, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('program_upper_lower_rotating_3', NULL, 'Rotating Upper/Lower 3', 'Three sessions a week rotating continuously through Upper and Lower, so the pattern shifts week to week without any scheduling.', 'upper_lower', 'Anyone who wants upper/lower''s frequency benefits but can only commit to three days.', 'intermediate', 3, 45, 55, 'strength_and_muscle', NULL, 'Only two templates rotate continuously, so one week runs Upper/Lower/Upper and the next runs Lower/Upper/Lower — everything still gets trained roughly twice a week on average.', 'Add weight per exercise once every set reaches the top of the range at target RIR.', 'Every 6-8 weeks, cut sets by about a third for one week at the same weights.', false, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('program_strength_longevity_hybrid_3', NULL, 'Strength + Longevity Hybrid 3', 'A full-body strength foundation with unilateral, carry and anti-rotation work layered in for lasting functional capacity.', 'hybrid', 'Adults who want to stay strong, stable and mobile for the long term, not just add plates to the bar.', 'intermediate', 3, 45, 55, 'longevity', ARRAY['general_fitness', 'strength_and_muscle']::text[], 'Every session pairs a heavy bilateral lift with a unilateral or stability movement — strength and the capability to use it are trained together, not treated as separate goals.', 'Main lifts progress on load once every set hits the top of the range at target RIR; carries and stability work progress on time or distance first.', 'Every 6 weeks, reduce every exercise by one set for a week regardless of how training has felt.', false, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z'),
  ('program_return_to_training_3', NULL, 'Return-to-Training Full Body 3', 'A deliberately conservative full-body restart — three or four exercises a session, generous rest, higher RIR throughout.', 'full_body', 'Anyone coming back to the gym after a long break, an injury, or an illness.', 'beginner', 3, 30, 40, 'return_to_training', ARRAY['general_fitness']::text[], 'The first job after time away is rebuilding the habit and the movement pattern, not chasing numbers — every set here is left comfortably short of hard.', 'Spend the first two weeks simply repeating comfortable weights to rebuild consistency, then apply the normal rule: add weight once every set reaches the top of the range at target RIR.', 'Not applicable in the usual sense — the whole programme runs at a deload-like intensity until a normal programme feels appropriate again.', false, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z')
